import {
  PlaneGeometry,
  Mesh,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec3,
  mix,
  sin,
  texture,
  uniform,
} from 'three/tsl';

/**
 * Creates a static card plane with gradient overlay and subtle grain.
 * The texture is loaded async and composited via TSL node material.
 */
export default function createNode(config, ctx) {
  // Aspect ratio from atlas region: 512x320 -> 1.6
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial();

  // TSL nodes for gradient and grain
  const baseGradient = mix(
    vec3(0.043, 0.043, 0.062), // surface #0b0b10
    vec3(0.91, 0.93, 0.95),   // paper #e8ecf2
    uv().y
  );
  // Static grain using high-frequency sin
  const grain = sin(uv().x * 100.0 + uv().y * 100.0).mul(0.03);

  // Prepare texture uniform (will be set after async load)
  const texUniform = uniform(null);
  const sampledTexture = texture(texUniform, uv());

  // Composite: texture base blended with gradient, plus grain
  const blended = mix(sampledTexture, baseGradient, 0.4).add(grain);
  material.colorNode = blended;

  // Start texture loading
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  let loadedTexture = null;
  texturePromise.then((tex) => {
    loadedTexture = tex;
    texUniform.value = tex;
    tex.wrapS = tex.wrapT = ctx.THREE.RepeatWrapping; // optional
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);

  // No handlers, no primitives – static node
  mesh.userData.handlers = {};

  // Cleanup: dispose geometry, material, and texture
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // No GSAP timelines to kill
  };

  return mesh;
}
